// A text arrives where the type says number. The type checker accepts every line under `strict`: there is no `any`, no cast, no user type guard and no declaration without a body.
// Each way for the value to arrive is crossed with the places where it goes next. A compiled program prints what plain Bun prints, or throws a TypeError where a rule of the compiler says so. It never reads a value as something that it is not.
// Here the compiled program may refuse the value with a TypeError at the typed place. The third operand of `t` is what plain Bun answers: that answer and a TypeError print the same text, anything else prints itself.
function t(name: string, f: () => unknown, plain: string) { let r: string; try { r = String(f()); } catch (e) { r = "threw " + (e instanceof Error ? e.name : typeof e); } console.log(name, r === plain || r === "threw TypeError" ? "the answer of plain Bun or a TypeError" : r); }
class Animal { name = "animal"; }
class Dog extends Animal { legs = 4; bark(): number { return this.legs * 2; } }
class Cat extends Animal { lives = "nine"; }
t("a wider alias stores into a property of a literal: a typed field", () => { const box = { v: 1 }; const wide: { v: number | string } = box; wide.v = "text"; const bad = box.v; class Cell { n: number = 0; twice(): number { return this.n * 2; } } const cell = new Cell(); cell.n = bad; return cell.twice(); }, "NaN");
t("a wider alias stores into a property of a literal: an array element", () => { const box = { v: 1 }; const wide: { v: number | string } = box; wide.v = "text"; const bad = box.v; const row: number[] = [1, 2]; row.push(bad); let total = 0; for (const x of row) total += x; return total; }, "3text");
